                    .strokeBorder(inUse ? Color.accentColor : Color.secondary.opacity(0.35),
                                  lineWidth: inUse ? 1.5 : 1)
            }
            .background(.thinMaterial, in: RoundedRectangle(cornerRadius: 6))

